-- BEGIN 020_normalize_account_type_labels.sql
-- Migration 020: use one canonical label for CyberArk-managed accounts.
-- Legacy imports/designs used INTERNO CYBERARK, CyberArk Managed, or
-- CYBERARK_MANAGED for the same category. NO NOMINAL remains separate.

BEGIN;

WITH normalized AS (
  SELECT
    grouped.safe_number,
    jsonb_object_agg(normalized_key, to_jsonb(total_count)) AS account_types
  FROM (
    SELECT
      m.safe_number,
      CASE
        WHEN upper(trim(type.key)) IN (
          'INTERNO CYBERARK', 'CYBERARK MANAGED', 'CYBERARK_MANAGED'
        ) THEN 'CYBERARK MANAGED'
        ELSE upper(trim(type.key))
      END AS normalized_key,
      sum(type.value::integer) AS total_count
    FROM public.cyberark_safe_metadata m
    CROSS JOIN LATERAL jsonb_each_text(coalesce(m.inventory_account_types, '{}'::jsonb)) AS type(key, value)
    GROUP BY m.safe_number,
      CASE
        WHEN upper(trim(type.key)) IN (
          'INTERNO CYBERARK', 'CYBERARK MANAGED', 'CYBERARK_MANAGED'
        ) THEN 'CYBERARK MANAGED'
        ELSE upper(trim(type.key))
      END
  ) AS grouped
  GROUP BY safe_number
)
UPDATE public.cyberark_safe_metadata AS target
SET inventory_account_types = normalized.account_types
FROM normalized
WHERE target.safe_number = normalized.safe_number
  AND target.inventory_account_types IS DISTINCT FROM normalized.account_types;

COMMIT;
-- END 020_normalize_account_type_labels.sql

-- BEGIN 021_cyberark_accounts.sql
-- Migration 021: persist the non-secret account inventory for Safe visibility.
-- Account passwords and secret payloads are never stored here.
BEGIN;

CREATE TABLE IF NOT EXISTS public.cyberark_accounts (
  account_row_id       BIGSERIAL PRIMARY KEY,
  safe_number          INT NOT NULL REFERENCES public.safes(safe_number),
  account_id           TEXT NOT NULL,
  account_name         TEXT NOT NULL,
  user_name            TEXT,
  address              TEXT,
  platform_id          TEXT,
  platform_name        TEXT,
  lifecycle_status     TEXT NOT NULL DEFAULT 'active'
                       CHECK (lifecycle_status IN ('active', 'retired')),
  first_seen_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  source_run_id        UUID,
  attributes           JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (safe_number, account_id)
);

CREATE INDEX IF NOT EXISTS idx_cyberark_accounts_safe_lifecycle
  ON public.cyberark_accounts (safe_number, lifecycle_status);
CREATE INDEX IF NOT EXISTS idx_cyberark_accounts_name
  ON public.cyberark_accounts (lower(account_name));
CREATE INDEX IF NOT EXISTS idx_cyberark_accounts_platform
  ON public.cyberark_accounts (platform_id);

COMMIT;
-- END 021_cyberark_accounts.sql

-- BEGIN 022_first_login_password_change.sql
-- Migration 022: force administrator-created local users to replace temporary passwords.
BEGIN;
ALTER TABLE public.access_users ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN NOT NULL DEFAULT false;
COMMIT;
-- END 022_first_login_password_change.sql

-- BEGIN 023_domain_access_permissions.sql
-- Migration 023: per-domain access permissions (Admin / PAM / DLP / DSPM).
--
-- OpenDS groups its workspaces under product domains. A role must hold
-- `domain:<id>` to see that domain in the workspace switcher. PAM is the
-- current product, so every authenticated role keeps it. Admin (platform
-- governance: users + activity) stays admin-only, matching the
-- `access:manage` gate already enforced on its routes. DLP and DSPM are not
-- granted to anyone yet — those modules do not exist; granting happens in a
-- later migration when they ship.
BEGIN;

INSERT INTO public.access_role_permissions (role_code, permission_code) VALUES
  ('reader',   'domain:pam'),
  ('operator', 'domain:pam'),
  ('admin',    'domain:pam'),
  ('admin',    'domain:admin')
ON CONFLICT (role_code, permission_code) DO NOTHING;

COMMIT;
-- END 023_domain_access_permissions.sql

-- BEGIN 024_ingestion_run_change_breakdown.sql
-- Migration 024: per-run change breakdown for the sync history.
--
-- cyberark_ingestion_runs already records how many safes/members were
-- received and how many errors occurred, but not how the inventory moved
-- (created vs updated vs retired) nor who started the run. run_ingestion
-- already computes these numbers per entry (ingest_entry returns
-- safe_inserted / members_inserted / members_updated, reconcile_inventory
-- returns the retired counts) and simply discards them. These columns let
-- the history panel show a real diff over time. All nullable / default 0 so
-- existing rows and the auto-baseline stay valid.
BEGIN;

ALTER TABLE public.cyberark_ingestion_runs
  ADD COLUMN IF NOT EXISTS triggered_by      TEXT,
  ADD COLUMN IF NOT EXISTS safes_created     INTEGER NOT NULL DEFAULT 0 CHECK (safes_created   >= 0),
  ADD COLUMN IF NOT EXISTS safes_updated     INTEGER NOT NULL DEFAULT 0 CHECK (safes_updated   >= 0),
  ADD COLUMN IF NOT EXISTS safes_retired     INTEGER NOT NULL DEFAULT 0 CHECK (safes_retired   >= 0),
  ADD COLUMN IF NOT EXISTS members_created   INTEGER NOT NULL DEFAULT 0 CHECK (members_created >= 0),
  ADD COLUMN IF NOT EXISTS members_updated   INTEGER NOT NULL DEFAULT 0 CHECK (members_updated >= 0),
  ADD COLUMN IF NOT EXISTS members_retired   INTEGER NOT NULL DEFAULT 0 CHECK (members_retired >= 0),
  ADD COLUMN IF NOT EXISTS pam_synced        BOOLEAN NOT NULL DEFAULT FALSE;

COMMIT;
-- END 024_ingestion_run_change_breakdown.sql

-- BEGIN 025_source_aware_ingestion_runs.sql
-- Migration 025: make ingestion history explicit about its source and shape.
-- Existing PAM columns remain for backwards compatibility; generic counters
-- allow Identity Administration and SIA runs to use the same history safely.
BEGIN;

ALTER TABLE public.cyberark_ingestion_runs
  ADD COLUMN IF NOT EXISTS source_system TEXT NOT NULL DEFAULT 'cyberark'
    CHECK (source_system IN ('cyberark', 'identity_administration', 'sia')),
  ADD COLUMN IF NOT EXISTS received_object_count BIGINT NOT NULL DEFAULT 0
    CHECK (received_object_count >= 0),
  ADD COLUMN IF NOT EXISTS received_relationship_count BIGINT NOT NULL DEFAULT 0
    CHECK (received_relationship_count >= 0),
  ADD COLUMN IF NOT EXISTS retired_object_count BIGINT NOT NULL DEFAULT 0
    CHECK (retired_object_count >= 0),
  ADD COLUMN IF NOT EXISTS retired_relationship_count BIGINT NOT NULL DEFAULT 0
    CHECK (retired_relationship_count >= 0);

UPDATE public.cyberark_ingestion_runs
SET received_object_count = received_safe_count,
    received_relationship_count = received_member_count,
    retired_object_count = safes_retired,
    retired_relationship_count = members_retired
WHERE received_object_count = 0
  AND received_relationship_count = 0
  AND (received_safe_count > 0 OR received_member_count > 0);

CREATE INDEX IF NOT EXISTS idx_cyberark_ingestion_runs_source_started
  ON public.cyberark_ingestion_runs (source_system, started_at DESC);

COMMIT;
-- END 025_source_aware_ingestion_runs.sql

-- BEGIN 026_findings_engine.sql
-- Migration 026: versioned, evidence-backed posture findings.
-- Findings are derived from persisted CyberArk inventory; no secrets or raw
-- provider payloads are stored.
BEGIN;

CREATE TABLE IF NOT EXISTS public.cyberark_findings (
  finding_id         BIGSERIAL PRIMARY KEY,
  rule_id            TEXT NOT NULL,
  rule_version       TEXT NOT NULL,
  source_system      TEXT NOT NULL DEFAULT 'cyberark'
                     CHECK (source_system IN ('cyberark', 'identity_administration', 'sia')),
  subject_type       TEXT NOT NULL,
  subject_id         TEXT NOT NULL,
  title              TEXT NOT NULL,
  severity           TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  category           TEXT NOT NULL CHECK (category IN ('review', 'non_compliance', 'data_quality')),
  status             TEXT NOT NULL DEFAULT 'open'
                     CHECK (status IN ('open', 'acknowledged', 'resolved', 'excepted')),
  evidence           JSONB NOT NULL DEFAULT '{}'::jsonb,
  source_run_id      UUID REFERENCES public.cyberark_ingestion_runs(run_id),
  first_detected_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_detected_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at        TIMESTAMPTZ,
  exception_reason   TEXT,
  exception_until    TIMESTAMPTZ,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (rule_id, rule_version, source_system, subject_type, subject_id)
);

CREATE INDEX IF NOT EXISTS idx_cyberark_findings_status
  ON public.cyberark_findings (status, severity, last_detected_at DESC);
CREATE INDEX IF NOT EXISTS idx_cyberark_findings_subject
  ON public.cyberark_findings (subject_type, subject_id);

COMMIT;
-- END 026_findings_engine.sql

-- BEGIN 027_access_control_catalog.sql
-- Migration 027: internal access-control catalog for platform and product roles.
-- Product roles for Netskope and BigID are intentionally marked planned. They
-- describe future entitlements only; no provider integration is implied here.
BEGIN;

ALTER TABLE public.access_roles
  ADD COLUMN IF NOT EXISTS display_name TEXT,
  ADD COLUMN IF NOT EXISTS domain_code TEXT NOT NULL DEFAULT 'platform',
  ADD COLUMN IF NOT EXISTS lifecycle_status TEXT NOT NULL DEFAULT 'active',
  ADD COLUMN IF NOT EXISTS system_managed BOOLEAN NOT NULL DEFAULT true;

UPDATE public.access_roles
SET display_name = CASE role_code
    WHEN 'reader' THEN 'Lector de plataforma'
    WHEN 'operator' THEN 'Operador de plataforma'
    WHEN 'admin' THEN 'Administrador de plataforma'
    ELSE initcap(replace(role_code, '_', ' '))
  END
WHERE display_name IS NULL;

ALTER TABLE public.access_roles ALTER COLUMN display_name SET NOT NULL;

CREATE TABLE IF NOT EXISTS public.access_permissions (
  permission_code TEXT PRIMARY KEY,
  domain_code TEXT NOT NULL,
  resource_code TEXT NOT NULL,
  action_code TEXT NOT NULL,
  description TEXT NOT NULL,
  lifecycle_status TEXT NOT NULL DEFAULT 'active',
  system_managed BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

