-- BEGIN 028_composite_access_roles.sql
-- Migration 028: composable access roles by domain-level reference.
-- Composite roles never copy permissions. Effective permissions are resolved
-- through the selected base role for each domain.
BEGIN;

CREATE TABLE public.access_domains (
  domain_code TEXT PRIMARY KEY,
  display_name TEXT NOT NULL,
  lifecycle_status TEXT NOT NULL CHECK (lifecycle_status IN ('active', 'planned')),
  sort_order INTEGER NOT NULL DEFAULT 0
);

INSERT INTO public.access_domains
  (domain_code, display_name, lifecycle_status, sort_order)
VALUES
  ('platform', 'Plataforma', 'active', 10),
  ('pam', 'CyberArk PAM', 'active', 20),
  ('dlp', 'Netskope DLP', 'planned', 30),
  ('dspm', 'BigID DSPM', 'planned', 40)
ON CONFLICT (domain_code) DO NOTHING;

ALTER TABLE public.access_roles
  ADD COLUMN role_kind TEXT NOT NULL DEFAULT 'direct'
    CHECK (role_kind IN ('direct', 'composite'));

ALTER TABLE public.access_roles
  ALTER COLUMN domain_code DROP NOT NULL;

ALTER TABLE public.access_roles
  ADD CONSTRAINT access_roles_domain_fk
  FOREIGN KEY (domain_code) REFERENCES public.access_domains(domain_code);

ALTER TABLE public.access_roles
  ADD CONSTRAINT access_roles_kind_domain_check
  CHECK (
    (role_kind = 'direct' AND domain_code IS NOT NULL)
    OR (role_kind = 'composite' AND domain_code IS NULL)
  );

ALTER TABLE public.access_roles
  ADD CONSTRAINT access_roles_code_domain_unique
  UNIQUE (role_code, domain_code);

ALTER TABLE public.access_permissions
  ADD CONSTRAINT access_permissions_domain_fk
  FOREIGN KEY (domain_code) REFERENCES public.access_domains(domain_code);

CREATE TABLE public.access_domain_levels (
  domain_code TEXT NOT NULL REFERENCES public.access_domains(domain_code) ON DELETE RESTRICT,
  level_code TEXT NOT NULL,
  display_name TEXT NOT NULL,
  base_role_code TEXT NOT NULL UNIQUE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (domain_code, level_code),
  FOREIGN KEY (base_role_code, domain_code)
    REFERENCES public.access_roles(role_code, domain_code) ON DELETE RESTRICT
);

INSERT INTO public.access_domain_levels
  (domain_code, level_code, display_name, base_role_code, sort_order)
VALUES
  ('platform', 'reader', 'Lector', 'reader', 10),
  ('platform', 'operator', 'Operador', 'operator', 20),
  ('platform', 'admin', 'Administrador', 'admin', 30),
  ('pam', 'reader', 'Lector', 'cyberark_reader', 10),
  ('pam', 'operator', 'Operador', 'cyberark_operator', 20),
  ('pam', 'admin', 'Administrador', 'cyberark_admin', 30),
  ('dlp', 'reader', 'Lector', 'netskope_reader', 10),
  ('dlp', 'admin', 'Administrador', 'netskope_admin', 30),
  ('dspm', 'reader', 'Lector', 'bigid_reader', 10),
  ('dspm', 'admin', 'Administrador', 'bigid_admin', 30)
ON CONFLICT (domain_code, level_code) DO NOTHING;

CREATE TABLE public.access_custom_role_levels (
  custom_role_code TEXT NOT NULL REFERENCES public.access_roles(role_code) ON DELETE CASCADE,
  domain_code TEXT NOT NULL,
  level_code TEXT NOT NULL,
  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (custom_role_code, domain_code),
  FOREIGN KEY (domain_code, level_code)
    REFERENCES public.access_domain_levels(domain_code, level_code) ON DELETE RESTRICT
);

CREATE INDEX idx_access_custom_role_levels_selection
  ON public.access_custom_role_levels (domain_code, level_code);

CREATE VIEW public.access_effective_role_permissions AS
SELECT role_code, permission_code
FROM public.access_role_permissions
UNION
SELECT selection.custom_role_code AS role_code,
       permission.permission_code
FROM public.access_custom_role_levels selection
JOIN public.access_domain_levels level
  ON level.domain_code = selection.domain_code
 AND level.level_code = selection.level_code
JOIN public.access_role_permissions permission
  ON permission.role_code = level.base_role_code;

COMMIT;
-- END 028_composite_access_roles.sql

-- BEGIN 029_user_dashboard_preferences.sql
-- Migration 029: personal PAM dashboard metric selection.
-- actor_id is intentionally not a foreign key because OIDC identities may
-- have role assignments without a local access_users row.
BEGIN;

CREATE TABLE public.user_dashboard_preferences (
  actor_id TEXT PRIMARY KEY,
  widgets JSONB NOT NULL DEFAULT '[]'::JSONB,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT user_dashboard_widgets_array CHECK (jsonb_typeof(widgets) = 'array'),
  CONSTRAINT user_dashboard_widget_limit CHECK (jsonb_array_length(widgets) <= 6)
);

COMMIT;
-- END 029_user_dashboard_preferences.sql

-- BEGIN 030_account_inventory_classification.sql
-- Migration 030: explicit account-level inventory classification.
-- This is intentionally separate from Safe-level inventory_scope because a
-- Safe may contain both business and CyberArk-internal accounts.
BEGIN;

ALTER TABLE public.cyberark_accounts
  ADD COLUMN IF NOT EXISTS inventory_account_type TEXT
    CHECK (inventory_account_type IN ('nominal', 'no_nominal', 'internal'));

CREATE INDEX IF NOT EXISTS idx_cyberark_accounts_inventory_type
  ON public.cyberark_accounts (inventory_account_type);

COMMIT;
-- END 030_account_inventory_classification.sql

-- BEGIN 031_safe_account_type_classification.sql
-- Migration 031: explicit Safe-level account type classification.
-- This is separate from inventory_scope (business/internal Safe scope).
BEGIN;

ALTER TABLE public.cyberark_safe_metadata
  ADD COLUMN IF NOT EXISTS account_type_classification TEXT
    CHECK (account_type_classification IN ('nominal', 'no_nominal', 'internal'));

CREATE INDEX IF NOT EXISTS idx_cyberark_safe_metadata_account_type
  ON public.cyberark_safe_metadata (account_type_classification);

COMMIT;
-- END 031_safe_account_type_classification.sql

-- BEGIN 032_connection_inventory.sql
-- Migration 032: imported connection inventory for PAM/SIA coverage review.
-- The imported source is kept separate from verified CyberArk/SIA observations.
BEGIN;

CREATE TABLE IF NOT EXISTS public.connection_inventory_imports (
  import_id       UUID PRIMARY KEY,
  file_name       TEXT NOT NULL,
  row_count       INT NOT NULL CHECK (row_count >= 0),
  imported_by     TEXT NOT NULL,
  is_current      BOOLEAN NOT NULL DEFAULT TRUE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_connection_inventory_one_current
  ON public.connection_inventory_imports (is_current)
  WHERE is_current IS TRUE;

CREATE TABLE IF NOT EXISTS public.connection_inventory (
  inventory_id       BIGSERIAL PRIMARY KEY,
  import_id          UUID NOT NULL REFERENCES public.connection_inventory_imports(import_id),
  source_row_number  INT NOT NULL CHECK (source_row_number >= 2),
  instance_name      TEXT NOT NULL,
  environment        TEXT NOT NULL DEFAULT '',
  private_ip         TEXT NOT NULL,
  port               INT CHECK (port IS NULL OR (port >= 1 AND port <= 65535)),
  ca_sia             BOOLEAN,
  ca_dba             BOOLEAN,
  zsp_implemented     BOOLEAN,
  access_available    BOOLEAN,
  description        TEXT NOT NULL DEFAULT '',
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (import_id, source_row_number)
);

CREATE INDEX IF NOT EXISTS idx_connection_inventory_import_ip
  ON public.connection_inventory (import_id, lower(private_ip));
CREATE INDEX IF NOT EXISTS idx_connection_inventory_instance
  ON public.connection_inventory (import_id, lower(instance_name));

COMMIT;
-- END 032_connection_inventory.sql

-- BEGIN 033_expand_dashboard_widgets.sql
-- Migration 033: allow up to twelve widgets in the personal dashboard.
-- Existing preferences remain valid; this only expands the JSON array limit.
BEGIN;

ALTER TABLE public.user_dashboard_preferences
  DROP CONSTRAINT user_dashboard_widget_limit,
  ADD CONSTRAINT user_dashboard_widget_limit CHECK (jsonb_array_length(widgets) <= 12);

COMMIT;
-- END 033_expand_dashboard_widgets.sql

