-- BEGIN 037_durable_sync_queue.sql
-- Migration 037: durable, observable queue state for source-isolated sync runs.
-- Reuses cyberark_ingestion_runs as the job record; run_id remains the source-run ID.
BEGIN;

ALTER TABLE public.cyberark_ingestion_runs
  DROP CONSTRAINT IF EXISTS cyberark_ingestion_runs_status_check;

ALTER TABLE public.cyberark_ingestion_runs
  ADD CONSTRAINT cyberark_ingestion_runs_status_check
    CHECK (status IN ('queued', 'running', 'completed', 'partial', 'failed'));

ALTER TABLE public.cyberark_ingestion_runs
  ADD COLUMN IF NOT EXISTS enqueued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ADD COLUMN IF NOT EXISTS run_options JSONB NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS stage TEXT,
  ADD COLUMN IF NOT EXISTS progress_current BIGINT NOT NULL DEFAULT 0
    CHECK (progress_current >= 0),
  ADD COLUMN IF NOT EXISTS progress_total BIGINT
    CHECK (progress_total IS NULL OR progress_total >= 0),
  ADD COLUMN IF NOT EXISTS status_message TEXT,
  ADD COLUMN IF NOT EXISTS attempt_count SMALLINT NOT NULL DEFAULT 0
    CHECK (attempt_count >= 0),
  ADD COLUMN IF NOT EXISTS worker_id TEXT,
  ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS lease_expires_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS idempotency_key UUID;

CREATE INDEX IF NOT EXISTS idx_ingestion_runs_queue_dispatch
  ON public.cyberark_ingestion_runs (status, enqueued_at)
  WHERE status = 'queued';

CREATE INDEX IF NOT EXISTS idx_ingestion_runs_source_queue_dispatch
  ON public.cyberark_ingestion_runs (source_system, status, enqueued_at)
  WHERE status = 'queued';

CREATE UNIQUE INDEX IF NOT EXISTS idx_ingestion_runs_actor_idempotency
  ON public.cyberark_ingestion_runs (triggered_by, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

COMMIT;
-- END 037_durable_sync_queue.sql

-- BEGIN 038_pam_technical_catalogs.sql
-- Migration 038: widen the normalized CMDB object graph to cover the
-- technical PAM catalogs verified against the tenant on 2026-09-10
-- (SYS-001, PSM-001, PLAT-003, AIM-001). Aditiva: solo amplia el CHECK
-- existente de object_type, no toca filas ni columnas ya persistidas.
BEGIN;

ALTER TABLE public.cyberark_inventory_objects
  DROP CONSTRAINT IF EXISTS cyberark_inventory_objects_object_type_check;

ALTER TABLE public.cyberark_inventory_objects
  ADD CONSTRAINT cyberark_inventory_objects_object_type_check
    CHECK (object_type IN (
      'user', 'role', 'safe', 'platform', 'psm', 'access_policy', 'sia',
      'component', 'psm_connector', 'aim_application',
      'platform_dependent', 'platform_group', 'platform_rotational_group'
    ));

COMMIT;
-- END 038_pam_technical_catalogs.sql

-- BEGIN 039_pam_platform_targets.sql
-- Migration 039: PLAT-002 (CPM/workflow policy per destination "target"
-- platform) turned out to use its own numeric ID space and Name field that
-- only sometimes equals a PlatformID string -- joining it onto the existing
-- `platform` object by ID would silently misattribute policy to the wrong
-- row for the ~half that don't match. Model it as its own object type
-- instead of guessing a name-based join. Aditiva: solo amplia el CHECK.
BEGIN;

ALTER TABLE public.cyberark_inventory_objects
  DROP CONSTRAINT IF EXISTS cyberark_inventory_objects_object_type_check;

ALTER TABLE public.cyberark_inventory_objects
  ADD CONSTRAINT cyberark_inventory_objects_object_type_check
    CHECK (object_type IN (
      'user', 'role', 'safe', 'platform', 'psm', 'access_policy', 'sia',
      'component', 'psm_connector', 'aim_application',
      'platform_dependent', 'platform_group', 'platform_rotational_group',
      'platform_target'
    ));

COMMIT;
-- END 039_pam_platform_targets.sql

-- BEGIN 040_access_assets.sql
-- Migration 040: ACCESS-001 (Access space asset catalog). New independent
-- source_system = 'access', object_type = 'access_asset'. platformId is kept
-- only as an attribute; the PAM cross-reference is resolved with a read-time
-- exact-match join (see repositories/access_queries.py), the same pattern
-- already used for the SIA->PAM IP join and the Identity->PAM UUID bridge --
-- never a persisted cyberark_inventory_relationships row, since that table's
-- single source_system column can't represent an edge between two different
-- source systems. Aditiva: solo amplia el CHECK.
BEGIN;

ALTER TABLE public.cyberark_inventory_objects
  DROP CONSTRAINT IF EXISTS cyberark_inventory_objects_object_type_check;

ALTER TABLE public.cyberark_inventory_objects
  ADD CONSTRAINT cyberark_inventory_objects_object_type_check
    CHECK (object_type IN (
      'user', 'role', 'safe', 'platform', 'psm', 'access_policy', 'sia',
      'component', 'psm_connector', 'aim_application',
      'platform_dependent', 'platform_group', 'platform_rotational_group',
      'platform_target', 'access_asset'
    ));

COMMIT;
-- END 040_access_assets.sql

-- BEGIN 041_sia_and_identity_federation_catalogs.sql
-- Migration 041: SIA-CONN-001 (connectors), SIA-RES-001 (VM infrastructure)
-- and ID-001 (Identity Administration federations). All three confirmed
-- live against the tenant (2026-09-11) reusing already-authorized
-- credentials -- no new object_type space needed beyond widening the CHECK.
-- Aditiva: solo amplia el CHECK.
BEGIN;

ALTER TABLE public.cyberark_inventory_objects
  DROP CONSTRAINT IF EXISTS cyberark_inventory_objects_object_type_check;

ALTER TABLE public.cyberark_inventory_objects
  ADD CONSTRAINT cyberark_inventory_objects_object_type_check
    CHECK (object_type IN (
      'user', 'role', 'safe', 'platform', 'psm', 'access_policy', 'sia',
      'component', 'psm_connector', 'aim_application',
      'platform_dependent', 'platform_group', 'platform_rotational_group',
      'platform_target', 'access_asset',
      'sia_connector', 'sia_resource', 'identity_federation'
    ));

COMMIT;
-- END 041_sia_and_identity_federation_catalogs.sql

-- BEGIN 042_access_source_on_ingestion_runs.sql
-- Migration 042: ACCESS-001 left source_system = 'access' on inventory
-- objects (040) but never widened the ingestion-run CHECK from 025.
-- POST /api/ingestion/all/runs therefore fails with CheckViolation when
-- enqueueing the Access space job. Findings share the same allowlist.
-- Aditiva: solo amplia CHECKs existentes.
BEGIN;

ALTER TABLE public.cyberark_ingestion_runs
  DROP CONSTRAINT IF EXISTS cyberark_ingestion_runs_source_system_check;

ALTER TABLE public.cyberark_ingestion_runs
  ADD CONSTRAINT cyberark_ingestion_runs_source_system_check
    CHECK (source_system IN ('cyberark', 'identity_administration', 'sia', 'access'));

ALTER TABLE public.cyberark_findings
  DROP CONSTRAINT IF EXISTS cyberark_findings_source_system_check;

ALTER TABLE public.cyberark_findings
  ADD CONSTRAINT cyberark_findings_source_system_check
    CHECK (source_system IN ('cyberark', 'identity_administration', 'sia', 'access'));

COMMIT;
-- END 042_access_source_on_ingestion_runs.sql

-- BEGIN 043_sia_database_accounts_and_identity_federation.sql
-- Migration 043: SIA-STRONG-001 (database strong accounts) and ID-001
-- (Identity Administration federations, core fields only). Both confirmed
-- live against the tenant.
--
-- Database strong accounts get their OWN object_type ('sia_database_account')
-- instead of reusing 'sia_resource' (shared with SIA-RES-001 VMs): the
-- object_type is also the reconciliation scope (see
-- services/cmdb_persistence.reconcile_objects), and an install that only
-- configures CA_SIA_DB_STRONG_ACCOUNTS_PATH (not
-- CA_SIA_VM_INFRASTRUCTURE_PATH, or vice versa) must not have this run
-- retire the other catalog's previously-synced rows just because this run
-- never asked about them.
--
-- 'identity_federation' was already added to this CHECK in migration 041,
-- pending the Domains/Apps/CyberarkServices allowlist decision for ID-001;
-- that decision is now made (core fields only, see
-- services/identity_admin_mapping.py), so no CHECK change is needed for it
-- here — only services/cmdb_models.OBJECT_TYPES gains the entry.
--
-- Aditiva: solo amplia el CHECK.
BEGIN;

ALTER TABLE public.cyberark_inventory_objects
  DROP CONSTRAINT IF EXISTS cyberark_inventory_objects_object_type_check;

ALTER TABLE public.cyberark_inventory_objects
  ADD CONSTRAINT cyberark_inventory_objects_object_type_check
    CHECK (object_type IN (
      'user', 'role', 'safe', 'platform', 'psm', 'access_policy', 'sia',
      'component', 'psm_connector', 'aim_application',
      'platform_dependent', 'platform_group', 'platform_rotational_group',
      'platform_target', 'access_asset',
      'sia_connector', 'sia_resource', 'sia_database_account', 'identity_federation'
    ));

COMMIT;
-- END 043_sia_database_accounts_and_identity_federation.sql

-- BEGIN 044_pam_sia_identity_catalog_permissions.sql
-- Migration 044: split access:manage into narrower, purpose-built read
-- permissions for PAM/SIA/Identity technical catalogs.
--
-- Today the ONLY way to see PAM technical catalogs (platforms, PSM
-- connectors, components, AIM applications, Access space assets), SIA
-- connectors/resources/database accounts, or Identity Administration
-- federations is to hold access:manage -- the same permission that grants
-- full user/role administration. A PAM operator role (cyberark_operator)
-- has zero visibility into PAM's own technical catalogs today, even though
-- that data is squarely PAM's.
--
-- This migration is purely additive: access:manage keeps working exactly
-- as before (every route below now accepts EITHER access:manage OR the new
-- narrow permission, via require_any_permission -- see auth.py and
-- api/routes/cmdb.py). No existing role loses anything; cyberark_operator/
-- cyberark_admin (which previously had no access to these routes at all)
-- gain read visibility into PAM's own catalogs, and two new opt-in roles
-- (sia_reader, identity_reader) exist for granting SIA/Identity catalog
-- visibility without granting access:manage.
--
-- sia-policies/sia-destinations and identity-users/identity-roles are
-- deliberately left untouched (they already only require the baseline
-- inventory:read, an existing inconsistency noted separately in the
-- workspace audit but out of scope for this migration).
BEGIN;

INSERT INTO public.access_domains
  (domain_code, display_name, lifecycle_status, sort_order)
VALUES
  ('sia', 'Secure Infrastructure Access', 'active', 50),
  ('identity', 'Identity Administration', 'active', 60)
ON CONFLICT (domain_code) DO NOTHING;

INSERT INTO public.access_permissions
  (permission_code, domain_code, resource_code, action_code, description, lifecycle_status)
VALUES
  ('pam:catalogs_read', 'pam', 'catalogs', 'read', 'Consultar catálogos técnicos de PAM: plataformas, conectores PSM, componentes, aplicaciones AIM y assets de Access', 'active'),
  ('domain:sia', 'sia', 'domain', 'access', 'Ingresar al dominio SIA', 'active'),
  ('sia:catalogs_read', 'sia', 'catalogs', 'read', 'Consultar catálogos técnicos de SIA: conectores, recursos y cuentas fuertes de base de datos', 'active'),
  ('domain:identity', 'identity', 'domain', 'access', 'Ingresar al dominio Identity Administration', 'active'),
  ('identity:catalogs_read', 'identity', 'catalogs', 'read', 'Consultar el catálogo de federaciones de Identity Administration', 'active')
ON CONFLICT (permission_code) DO NOTHING;

INSERT INTO public.access_roles
  (role_code, description, display_name, domain_code, lifecycle_status, system_managed)
VALUES
  ('sia_reader', 'Lectura de catálogos técnicos SIA', 'SIA · Lector', 'sia', 'active', true),
  ('identity_reader', 'Lectura del catálogo de federaciones de Identity Administration', 'Identity · Lector', 'identity', 'active', true)
ON CONFLICT (role_code) DO NOTHING;

INSERT INTO public.access_domain_levels
  (domain_code, level_code, display_name, base_role_code, sort_order)
VALUES
  ('sia', 'reader', 'Lector', 'sia_reader', 10),
  ('identity', 'reader', 'Lector', 'identity_reader', 10)
ON CONFLICT (domain_code, level_code) DO NOTHING;

INSERT INTO public.access_role_permissions (role_code, permission_code) VALUES
  ('cyberark_operator', 'pam:catalogs_read'),
  ('cyberark_admin', 'pam:catalogs_read'),
  ('sia_reader', 'domain:sia'),
  ('sia_reader', 'sia:catalogs_read'),
  ('identity_reader', 'domain:identity'),
  ('identity_reader', 'identity:catalogs_read')
ON CONFLICT (role_code, permission_code) DO NOTHING;

COMMIT;
-- END 044_pam_sia_identity_catalog_permissions.sql

-- BEGIN 045_session_version.sql
-- Migration 045: session revocation on password change (PENTEST-004).
-- Adds a monotonically-incrementing version stamped on the session at
-- login; require_read_access/require_write_access compare it against the
-- current row on every session-based request, so a stolen cookie stops
-- working the moment the account's password is changed, reissued, reset
-- by an admin, or the account is deactivated -- without needing
-- server-side session storage.
BEGIN;

ALTER TABLE public.access_users
  ADD COLUMN IF NOT EXISTS session_version INTEGER NOT NULL DEFAULT 1;

COMMIT;
-- END 045_session_version.sql

-- BEGIN 046_rate_limit_attempts.sql
-- Migration 046: shared, atomic rate limiting for login/bootstrap (PENTEST-006).
-- The previous limiter (AttemptRateLimiter) was local to each process --
-- reset on restart and not coordinated across multiple workers -- and its
-- check() -> hash() -> failed() sequence let a concurrent burst pass the
-- check before any of it was recorded. This table backs a single atomic
-- UPSERT ("reserve the attempt, then verify the credential") shared by
-- every worker/process talking to the same database, closing both gaps.
BEGIN;

CREATE TABLE IF NOT EXISTS public.rate_limit_attempts (
    bucket_key TEXT PRIMARY KEY,
    window_started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    attempt_count INTEGER NOT NULL DEFAULT 0
);

COMMIT;
-- END 046_rate_limit_attempts.sql

-- BEGIN 047_rate_limit_attempts_retention_index.sql
-- Migration 047: index for bounded rate-limit retention (IF-001).
-- purge_expired_attempts() (app/repositories/rate_limiting.py) deletes rows
-- whose window closed more than retention_seconds ago, on a schedule (see
-- app/lifecycle.py). Without this index that purge -- and any future
-- monitoring query grouping by age -- would need a full table scan as the
-- table grows from unauthenticated, attacker-controlled traffic.
BEGIN;

CREATE INDEX IF NOT EXISTS idx_rate_limit_attempts_window_started_at
  ON public.rate_limit_attempts (window_started_at);

COMMIT;
-- END 047_rate_limit_attempts_retention_index.sql

-- BEGIN 048_security_events.sql
-- Migration 048: durable authentication/security events (PENTEST-008).
BEGIN;

CREATE TABLE IF NOT EXISTS public.access_security_events (
    event_id BIGSERIAL PRIMARY KEY,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    event_type TEXT NOT NULL,
    actor_id TEXT,
    result TEXT NOT NULL CHECK (result IN ('success', 'failure')),
    source_ip TEXT,
    request_id TEXT,
    mechanism TEXT,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS access_security_events_occurred_at_idx
    ON public.access_security_events (occurred_at DESC);
CREATE INDEX IF NOT EXISTS access_security_events_event_type_idx
    ON public.access_security_events (event_type);
CREATE INDEX IF NOT EXISTS access_security_events_actor_id_idx
    ON public.access_security_events (actor_id);

COMMIT;
-- END 048_security_events.sql
